import {ABYSS_GATE_COST,gateBossDefeated,floorAddress} from './descent-progress.js';
import {TOTAL_FLOORS,FLOORS_PER_BIOME} from './campaign.js';
import {BOSSES} from './bosses.js';
import {MATERIALS} from './materials.js';
import {elementLayoutScale} from './ui-display.js';
const bossFloor=20;
export function abyssRequirementView(profile){
 const complete=ABYSS_GATE_COST.map((required,i)=>profile.descent.gate[i]===required);
 return {bossName:BOSSES[Math.floor((bossFloor-1)/FLOORS_PER_BIOME)].name,code:floorAddress(bossFloor).code,bossDefeated:gateBossDefeated(profile),complete,completed:complete.filter(Boolean).length,total:complete.length,totalFloors:TOTAL_FLOORS,materials:MATERIALS.map(m=>m.name),bossArt:'assets/dungeon-refinement-v2/boss-3.svg',gateArt:'assets/abyss-gate-r2/gate-nav-4x-v01.png'};
}
const markup="<section class=\"bm-window\" aria-label=\"Requisito do Abismo\">\n  <header class=\"bm-head\"><img class=\"bm-emblem\" alt=\"\"><h2>Acesso ao Abismo</h2><button type=\"button\" class=\"bm-button bm-close cursor-interaction\" aria-label=\"Fechar\">×</button></header>\n  <div class=\"bm-body\">\n   <section class=\"bm-boss\" aria-label=\"Guardião necessário\"><img class=\"bm-portrait\" alt=\"Boss Místico\"><div class=\"bm-boss-copy\"><div class=\"bm-verb\">Vença o guardião</div><h3 class=\"bm-boss-name\"></h3><div class=\"bm-floor\"><small>Andar</small><strong></strong></div></div><b class=\"bm-boss-status\" aria-label=\"Ainda não vencido\">○</b></section>\n   <section class=\"bm-gate\" aria-label=\"Depósitos do portão\"><div class=\"bm-gate-name\"><h3>Portão</h3><p>Complete os depósitos</p></div><strong class=\"bm-count\"></strong><div class=\"bm-gems\" aria-label=\"Quatro cristais do portão\"></div></section>\n   <p class=\"bm-rule\"></p>\n  </div>\n  <footer class=\"bm-foot\"><button type=\"button\" class=\"bm-button bm-back cursor-interaction\">‹ Voltar ao Abismo</button></footer>\n </section>\n ";
export function mountAbyssRequirement(parent,{profile,onClose,focus=true,softMode=()=>false}={}){
 const doc=parent.ownerDocument,win=doc.defaultView,view=abyssRequirementView(profile),host=doc.createElement('section');host.id='gv-abyss-requirement';host.setAttribute('aria-label','Requisito do Abismo');host.innerHTML=markup;parent.append(host);const q=s=>host.querySelector(s),media=win.matchMedia('(prefers-reduced-motion:reduce)');let disposed=false;
 q('.bm-emblem').src=view.gateArt;q('.bm-portrait').src=view.bossArt;q('.bm-portrait').alt=view.bossName;q('.bm-close').onclick=onClose;q('.bm-back').id='gvl-overlay-back';q('.bm-back').dataset.primary='true';
 q('.bm-boss-name').textContent=view.bossName[0]+view.bossName.slice(1).toLocaleLowerCase('pt-BR');q('.bm-floor strong').textContent=view.code;q('.bm-boss-status').textContent=view.bossDefeated?'✓':'○';q('.bm-boss-status').setAttribute('aria-label',view.bossDefeated?'Vencido':'Ainda não vencido');q('.bm-boss').dataset.complete=String(view.bossDefeated);q('.bm-count').textContent=view.completed+' / '+view.total;q('.bm-gate').dataset.complete=String(view.completed===view.total);q('.bm-gate').setAttribute('aria-label',view.completed+' de '+view.total+' depósitos completos');q('.bm-rule').textContent='Sem moedas · não exige os '+view.totalFloors+' andares.';
 view.complete.forEach((done,i)=>{const node=doc.createElement('span');node.className='bm-gem';node.dataset.complete=String(done);node.setAttribute('role','img');node.setAttribute('aria-label',view.materials[i]+': '+(done?'completo':'pendente'));const image=doc.createElement('img');image.src='assets/refuge-night-v3/gem-'+i+'.png';image.alt='';const mark=doc.createElement('b');mark.setAttribute('aria-hidden','true');mark.textContent=done?'✓':'○';node.append(image,mark);q('.bm-gems').append(node);});
 function fit(){if(disposed)return;const scale=elementLayoutScale(host)||1,scene=win.getComputedStyle(parent),live=parent.parentElement.querySelector('#gvl-live'),available=(win.innerHeight-24)/scale-(parseFloat(scene.paddingTop)||0)-(parseFloat(scene.paddingBottom)||0)-(live?.offsetHeight||0);q('.bm-window').style.maxHeight=Math.max(180,available)+'px';host.dataset.soft=String(softMode()||media.matches);}
 function key(e){if(e.key!=='Tab')return;const stops=[q('.bm-close'),q('.bm-back')],active=host.getRootNode().activeElement,i=stops.indexOf(active);if(i<0||e.shiftKey&&i===0||!e.shiftKey&&i===stops.length-1){e.preventDefault();stops[e.shiftKey?1:0].focus({preventScroll:true});}e.stopPropagation();}
 const resize=new win.ResizeObserver(fit);resize.observe(host);host.addEventListener('keydown',key);win.addEventListener('resize',fit);media.addEventListener('change',fit);fit();if(focus)q('.bm-back').focus({preventScroll:true});
 return()=>{if(disposed)return;disposed=true;resize.disconnect();host.removeEventListener('keydown',key);win.removeEventListener('resize',fit);media.removeEventListener('change',fit);host.remove();};
}
